    "id": "ch3-function",
    "title": "Functions",
    "minutes": 9,
    "md": "function\n\nfunction declaration\n\n```js\nfunction a() {\n    console.log(1);\n}\na() // 1\nfunction b(a){ // params\n    console.log(a);\n}\nb(2) // 2    // args\nfunction a(){ // func call\n\tconsole.log(2)\n\treturn 1\n}\nlet r\n(r = a)()  // we can do it like this, remember when use (expresion) we should use ; before it so it does not compile into single line ny jS\n```\n\n```text\nit is split like this:\nr = a\nr()\nfunction c(a = 3){  // es6 => default parameter\n    console.log(a);\n}\nc() // 3\n```\n\ndefault parameter\n\n```js\nfunction check() {\n    throw new Error(\"param required\")\n}\nfunction show(name = check()) {\n    console.log(name)\n}\nshow() // param required\nshow(\"Saud\")  // Saud\n```\n\nfunction expression\n\n```js\nlet d = function() {  // anonymous func\n    console.log(4);\n}\nd() // 4\n```\n\ncallback func, high order function\n\n```js\nfunction e(f) {\n    f()\n}\n```\n\nA callback is just a function that's passed into another function,\n\nwith the expectation that the callback will be called at the appropriate time.\n\n```js\ne(() => {console.log(\"callback function!\");\n})\n```\n\narrow func\n\n```js\nlet e = () => {\n    console.log(5);\n}\ne() // 5\nlet f = a => {\n    console.log(a);\n}\nf(6) // 6\nlet g = a => console.log(a);\ng(7); // 7\n```\n\niife -> immediately invoked function expression\n\n```js\n(function() {\n    console.log(1);\n})() // 1\n```\n\npure function: same input -> same output, no global var modify or dependence, does not changes outer var\n\n```js\nfunction abc(a) {\n    console.log(a);\n}\nabc(\"ok\")\nabc(\"ok\")\nimpure function: same input -> diff output eg: Math.random, modifies external state eg: counter++\nlet b  = 2\nfunction abc2(a){\n    console.log(a + b);\n}\nabc2(\"ok\") // ok2\nb = 1\nabc2(\"ok\") // ok1\n```\n\nmodifies external state\n\n```js\nlet c = 0\nfunction increment(x) {\n    c++\n    return c\n}\nincrement(0) // 1\nincrement(0) // 2\n```\n\n```js\nfunction outer() {\n    let count = 0; // `count` is in the outer function's scope\n    function inner() {\n      count++; // Inner function accesses `count`\n      console.log(count);\n    }\n    return inner; // Return the inner function (creates a closure)\n  }\n  const counter = outer(); // `counter` is now the `inner` function + its lexical scope\n  counter(); // 1\n  counter(); // 2\n  counter(); // 3\n```\n\nA closure is a function that has access to the parent scope, after the parent function has closed.\n\nA closure is a function that remembers its outer variables and can access them\n\nClosures has historically been used to:\n\nCreate private variables\n\nPreserve state between function calls\n\nSimulate `block-scoping` before let and const existed\n\nImplement certain design patterns like currying and memoization\n\ncurrying\n\n```js\nfunction a(){\n\treturn function(){\n\t\tconsole.log(\"ok\")\n\t}\n}\na()() // ok\n```\n\n```js\nfunction a(){\n\treturn function b(){\n\t\tconsole.log(\"ok\")\n\t}\n}\na()()  // ok\nlet c = a()\nc()  // ok\n```\n\ncurrying\n\n```js\nfunction add(x){\n\treturn function (y){\n\t\tconsole.log( x + y)\n\t}\n}\nlet r = add(2) // x=2\nr(2) // 4   y=2\nr(2) // 4   y=2\nr(3) // 5   y=3\n```\n\nmemoize func\n\n```js\nfunction memoizedAdd(fn){\n\tlet m = new Map()\n\treturn function memoize(...args){\n\t\tconst key = JSON.stringify(args.sort((a,b) => a - b))\n\t\tif(m.has(key)){\n\t\t\tconsole.log(\"Returned from cached\")\n\t\t\tconsole.log(key)\n\t\t\treturn m.get(key)\n\t\t}\n\t\tconsole.log(\"Computing new result\")\n\t\tconst result = fn(...args)\n\t\tm.set(key, result)\n\t\tconsole.log(key)\n\t\treturn m.get(key)\n\t}\n}\nconst add = (a,b) => a+b\nconst memo = memoizedAdd(add)\nconsole.log(memo(1,2))\nconsole.log(memo(1,2))\nconsole.log(memo(2,1))\nconsole.log(memo(1,2))\nconsole.log(memo(1,3))\nconsole.log(memo(1,2))\n```\n\nsimplifed code memoize add\n\n```js\nfunction mAdd(fn) {\n\t\tlet map = new Map()\n\treturn function memo(x, y) {\n\t\tlet k = JSON.stringify([x,y])\n\t\tif(map.has(k)) {\n\t\t\tconsole.log(\"yes cahced\")\n\t\t\tconsole.log('key: ', k)\n\t\t\tconsole.log(map.get(k))\n\t\t}\n\t\telse {\n\t\t\tconsole.log('no')\n\t\t\tlet r = fn(x,y)\n\t\t\tconsole.log(r)\n\t\t\tconsole.log('key: ', k)\n\t\t\tmap.set(k, r)\n\t\t\tconsole.log(\"map: \", map)\n\t\t\tconsole.log(\"get \",map.get(k))\n\t\t}\n\t}\n}\nlet fn = (x,y) => x+y\nlet add = mAdd(fn)\nadd(1,1) // no\nadd(1,1) // yes cached\n```\n\nFactory Functions\n\nFactory functions are functions that return objects. They are useful for creating multiple instances of similar objects without the need for constructor functions.\n\n```js\nfunction createPerson(name, age) {\n  return {\n```\n\nname: name,\n\nage: age,\n\n```js\n  };\n}\nconst user=createPerson('John',30)\nconsole.log(user) //{name: 'John', age: 30}\n```\n\nIf a function invocation is preceded with the new keyword, it is a constructor invocation.\n\nThis is a function constructor:\n\n```js\nfunction myFunction(arg1, arg2) {\n  this.firstName = arg1;\n  this.lastName  = arg2;\n}\n```\n\n```text\nThis creates a new object\nconst myObj = new myFunction(\"John\", \"Doe\");  // new keyword is preceeded before the function invocation\n```\n\n```text\nThis will return \"John\"\nmyObj.firstName;\n```\n\n```js\ncall(), apply(), bind()\n```\n\nKey Differences\n\n| Method | When Executed | Arguments | Returns |\n| --- | --- | --- | --- |\n| call() | Immediately | Individual | Function result |\n| apply() | Immediately | Array | Function result |\n| bind() | Later (when called) | Individual | New function |\n\nall this does not works on arrow function\n\n#### call(): Call with specific this\n\n```js\nfunction msg(message, newmsg) {\n    console.log(message, this.name, newmsg)\n}\nconst person = { name: \"Saud\"}\ncall() calls the msg function with specific this and arguments\nmsg.call(person, \"Hi\", \"ok\") // Hi, Saud, ok\n```\n\n#### apply(): Call with array of arguments\n\n```js\nfunction intro(age, city) {\n    console.log(\"Name: \", this.name, \"Age: \", age, \"City: \", city)\n}\nconst person = { name: \"Art\"}\nintro.apply(person, [20, \"Mumbai\"])\n```\n\n#### bind(): Create New function with bound this\n\n```js\nfunction sayHi(){\n    console.log(\"Hi\", this.name)\n}\nconst person = { name: \"Saud\"}\nconst boundHi = sayHi.bind(person)\nboundHi() // Hi Saud\n```\n\nsummary\n\n```js\nfunction add(a, b) {\n  console.log(this.name, a + b);\n}\nconst context = { name: \"Calculator\" };\nadd.call(context, 5, 3);     // \"Calculator 8\"\nadd.apply(context, [5, 3]);  // \"Calculator 8\"\nconst boundAdd = add.bind(context, 5);\nboundAdd(3);                 // \"Calculator 8\"\n```\n\nSimple Rule:\n\n```js\nUse call() when you know all arguments and want to call immediately\nUse apply() when you have arguments as an array\nUse bind() when you want to create a new function to call later\n```\n\nAll three let you control the this value in functions! 🎯\n\nFactory Function Pattern\n\n```js\nfunction createObj(name) {\n  return {\n```\n\nname,\n\n```js\n    show: () => console.log(name) // ✅ Captures name from closure\n  }\n}\nlet obj2 = createObj(\"ok\")\nobj2.show()                    // \"ok\" ✅\n```\n\n```js\nconst myArray = [\"zero\", \"one\", \"two\"];\nconst myBoundMethod = function (sProperty) {\n  console.log(arguments.length > 0 ? this[sProperty] : this);  // if an argument is provided, access the property of 'this' using that argument; otherwise, log 'this' itself\n}.bind(myArray);\nmyBoundMethod(); // prints [\"zero,one,two\"] because 'this' is bound to myArray in the function\nmyBoundMethod(1); // prints \"one\"\nsetTimeout(myBoundMethod, 1.0 * 1000); // still prints [\"zero,one,two\"] after 1 second because of the binding\nsetTimeout(myBoundMethod, 1.5 * 1000, \"1\"); // prints \"one\" after 1.5 seconds\n```\n",
